from ...shipping.models import ShippingZone


def get_default_channel_slug_or_graphql_error() -> SimpleLazyObject:
    """Return a default channel slug in lazy way or a GraphQL error.

    Utility to get the default channel in GraphQL query resolvers.
    """
    return SimpleLazyObject(lambda: get_default_channel_or_graphql_error().slug)


def get_default_channel_or_graphql_error() -> Channel:
    """Return a default channel or a GraphQL error.

    Utility to get the default channel in GraphQL query resolvers.
    """
    try:
        channel = get_default_channel()
    except (ChannelNotDefined, NoDefaultChannel) as e:
        raise GraphQLError(str(e))
    else:
        return channel


def validate_channel(channel_slug, error_class):
    try:
        channel = Channel.objects.get(slug=channel_slug)
    except Channel.DoesNotExist:
        raise ValidationError(
            {
                "channel": ValidationError(
                    f"Channel with '{channel_slug}' slug does not exist.",
                    code=error_class.NOT_FOUND.value,
                )
            }
        )
    if not channel.is_active:
        raise ValidationError(
            {
                "channel": ValidationError(
                    f"Channel with '{channel_slug}' is inactive.",
                    code=error_class.CHANNEL_INACTIVE.value,
                )
            }
        )
    return channel


def clean_channel(
    channel_slug,
    error_class,
):
    if channel_slug is not None:
        channel = validate_channel(channel_slug, error_class)
    else:
        try:
            channel = get_default_channel()
        except ChannelNotDefined:
            raise ValidationError(
                {
                    "channel": ValidationError(
                        "You need to provide channel slug.",
                        code=error_class.MISSING_CHANNEL_SLUG.value,
                    )
                }
            )
    return channel


def delete_invalid_warehouse_to_shipping_zone_relations(
    channel, warehouse_ids, shipping_zone_ids=None, channel_deletion=False
):
    """Delete not valid warehouse-zone relations after channel updates.

    Look up for warehouse to shipping zone relations that will not have common channels
    after unlinking the given channel from warehouses or shipping zones.
    The warehouse can be linked with shipping zone only if common channel exists.
    """
    shipping_zone_ids = shipping_zone_ids or []

    ChannelWarehouse = Channel.warehouses.through  # type: ignore[attr-defined] # raw access to through model # noqa: E501
    ShippingZoneWarehouse = ShippingZone.warehouses.through  # type: ignore[attr-defined] # raw access to through model # noqa: E501
    ShippingZoneChannel = ShippingZone.channels.through

    shipping_zone_warehouses = ShippingZoneWarehouse.objects.filter(
        Q(warehouse_id__in=warehouse_ids) | Q(shippingzone_id__in=shipping_zone_ids)
    )
    channel_warehouses = ChannelWarehouse.objects.filter(
        Exists(shipping_zone_warehouses.filter(warehouse_id=OuterRef("warehouse_id")))
    )
    shipping_zone_channels = ShippingZoneChannel.objects.filter(
        Exists(
            shipping_zone_warehouses.filter(shippingzone_id=OuterRef("shippingzone_id"))
        )
    )

    warehouse_to_channel_ids = _get_warehouse_to_channels_mapping(
        channel, channel_warehouses, channel_deletion
    )
    zone_to_channel_ids = _get_shipping_zone_to_channels_mapping(shipping_zone_channels)
    shipping_zone_warehouses_to_delete = _get_invalid_shipping_zone_warehouses_ids(
        shipping_zone_warehouses, warehouse_to_channel_ids, zone_to_channel_ids
    )

    # delete invalid shipping zone - warehouse relations
    ShippingZoneWarehouse.objects.filter(
        id__in=shipping_zone_warehouses_to_delete
    ).delete()


def _get_warehouse_to_channels_mapping(channel, channel_warehouses, channel_deletion):
    warehouse_to_channel_ids = defaultdict(set)
    for warehouse_id, channel_id in channel_warehouses.values_list(
        "warehouse_id", "channel_id"
    ):
        # when the channel will be deleted so we do not want this channel in warehouse
        # channels set
        if not channel_deletion or channel_id != channel.id:
            warehouse_to_channel_ids[warehouse_id].add(channel_id)
    return warehouse_to_channel_ids


def _get_shipping_zone_to_channels_mapping(shipping_zone_channels):
    zone_to_channel_ids = defaultdict(set)
    for zone_id, channel_id in shipping_zone_channels.values_list(
        "shippingzone_id", "channel_id"
    ):
        zone_to_channel_ids[zone_id].add(channel_id)
    return zone_to_channel_ids


def _get_invalid_shipping_zone_warehouses_ids(
    shipping_zone_warehouses, warehouse_to_channel_ids, zone_to_channel_ids
):
    shipping_zone_warehouses_to_delete = []
    for id, zone_id, warehouse_id in shipping_zone_warehouses.values_list(
        "id", "shippingzone_id", "warehouse_id"
    ):
        warehouse_channels = warehouse_to_channel_ids.get(warehouse_id, set())
        zone_channels = zone_to_channel_ids.get(zone_id, set())
        # if there is no common channels between shipping zone and warehouse
        # the relation should be deleted
        if not warehouse_channels.intersection(zone_channels):
            shipping_zone_warehouses_to_delete.append(id)
    return shipping_zone_warehouses_to_delete

from enum import Enum
from functools import wraps
from typing import Iterable, List, Union

from graphene import ResolveInfo

from ..attribute import AttributeType
from ..core.exceptions import PermissionDenied
from ..permission.auth_filters import is_app, is_staff_user
from ..permission.enums import (
    BasePermissionEnum,
    PagePermissions,
    PageTypePermissions,
    ProductPermissions,
    ProductTypePermissions,
)
from ..permission.utils import (
    has_one_of_permissions,
    one_of_permissions_or_auth_filter_required,
)
from ..permission.utils import permission_required as core_permission_required
from .utils import get_user_or_app_from_context


def context(f):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            info = next(arg for arg in args if isinstance(arg, ResolveInfo))
            return func(info.context, *args, **kwargs)

        return wrapper

    return decorator


def account_passes_test(test_func):
    """Determine if user/app has permission to access to content."""

    def decorator(f):
        @wraps(f)
        @context(f)
        def wrapper(context, *args, **kwargs):
            test_func(context)
            return f(*args, **kwargs)

        return wrapper

    return decorator


def account_passes_test_for_attribute(test_func):
    """Determine if user/app has permission to access to content."""

    def decorator(f):
        @wraps(f)
        @context(f)
        def wrapper(context, *args, **kwargs):
            root = args[0]
            test_func(context, root)
            return f(*args, **kwargs)

        return wrapper

    return decorator


def permission_required(perm: Union[BasePermissionEnum, List[BasePermissionEnum]]):
    def check_perms(context):
        if isinstance(perm, Enum):
            perms = [perm]
        else:
            perms = perm

        requestor = get_user_or_app_from_context(context)
        if not core_permission_required(requestor, perms):
            raise PermissionDenied(permissions=perms)

    return account_passes_test(check_perms)


def one_of_permissions_required(perms: Iterable[BasePermissionEnum]):
    def check_perms(context):
        if not one_of_permissions_or_auth_filter_required(context, perms):
            raise PermissionDenied(permissions=perms)

    return account_passes_test(check_perms)


def _check_staff_member(context):
    if not is_staff_user(context):
        raise PermissionDenied(
            message=(
                "You need to be authenticated as a staff member to perform this action"
            )
        )


staff_member_required = account_passes_test(_check_staff_member)


def _check_staff_member_or_app(context):
    if not (is_app(context) or is_staff_user(context)):
        raise PermissionDenied(
            message=(
                "You need to be authenticated as a staff member or an app to perform "
                "this action"
            )
        )


staff_member_or_app_required = account_passes_test(_check_staff_member_or_app)


def check_attribute_required_permissions():
    """Check attribute permissions that depend on attribute type.

    As an attribute can belong to the product or to the page,
    different permissions need to be checked.
    """

    def check_perms(context, attribute):
        requestor = get_user_or_app_from_context(context)
        permissions: List[BasePermissionEnum]
        if attribute.type == AttributeType.PAGE_TYPE:
            permissions = [
                PagePermissions.MANAGE_PAGES,
                PageTypePermissions.MANAGE_PAGE_TYPES_AND_ATTRIBUTES,
            ]
        else:
            permissions = [
                ProductPermissions.MANAGE_PRODUCTS,
                ProductTypePermissions.MANAGE_PRODUCT_TYPES_AND_ATTRIBUTES,
            ]
        if not has_one_of_permissions(
            requestor,
            permissions,
        ):
            raise PermissionDenied(permissions=permissions)

    return account_passes_test_for_attribute(check_perms)

import hashlib
import logging
import traceback
from typing import TYPE_CHECKING, Any, Dict, Iterable, Union
from uuid import UUID

import graphene
from django.conf import settings
from django.db.models import Q, Value
from django.db.models.functions import Concat
from graphql import GraphQLDocument
from graphql.error import GraphQLError
from graphql.error import format_error as format_graphql_error

from ...account.models import User
from ...app.models import App
from ..core.enums import PermissionEnum
from ..core.types import TYPES_WITH_DOUBLE_ID_AVAILABLE, Permission
from ..core.utils import from_global_id_or_error

if TYPE_CHECKING:
    from ..core import SaleorContext

unhandled_errors_logger = logging.getLogger("saleor.graphql.errors.unhandled")
handled_errors_logger = logging.getLogger("saleor.graphql.errors.handled")


ERROR_COULD_NO_RESOLVE_GLOBAL_ID = (
    "Could not resolve to a node with the global id list of '%s'."
)
REVERSED_DIRECTION = {
    "-": "",
    "": "-",
}


def resolve_global_ids_to_primary_keys(
    ids: Iterable[str], graphene_type=None, raise_error: bool = False
):
    pks = []
    invalid_ids = []
    used_type = graphene_type

    for graphql_id in ids:
        if not graphql_id:
            invalid_ids.append(graphql_id)
            continue

        try:
            node_type, _id = from_global_id_or_error(graphql_id)
        except Exception:
            invalid_ids.append(graphql_id)
            continue

        # Raise GraphQL error if ID of a different type was passed
        if used_type and str(used_type) != str(node_type):
            if not raise_error:
                continue
            raise GraphQLError(f"Must receive {str(used_type)} id: {graphql_id}.")

        used_type = node_type
        pks.append(_id)

    if invalid_ids:
        raise GraphQLError(ERROR_COULD_NO_RESOLVE_GLOBAL_ID % invalid_ids)

    return used_type, pks


def _resolve_graphene_type(schema, type_name):
    type_from_schema = schema.get_type(type_name)
    if type_from_schema:
        return type_from_schema.graphene_type
    raise GraphQLError("Could not resolve the type {}".format(type_name))


def get_nodes(
    ids,
    graphene_type: Union[graphene.ObjectType, str, None] = None,
    model=None,
    qs=None,
    schema=None,
):
    """Return a list of nodes.

    If the `graphene_type` argument is provided, the IDs will be validated
    against this type. If the type was not provided, it will be looked up in
    the schema. Raises an error if not all IDs are of the same
    type.

    If the `graphene_type` is of type str, the model keyword argument must be provided.
    """
    nodes_type, pks = resolve_global_ids_to_primary_keys(
        ids, graphene_type, raise_error=True
    )
    # If `graphene_type` was not provided, check if all resolved types are
    # the same. This prevents from accidentally mismatching IDs of different
    # types.
    if nodes_type and not graphene_type:
        if schema:
            graphene_type = _resolve_graphene_type(schema, nodes_type)
        else:
            raise GraphQLError("GraphQL schema was not provided")

    if qs is None and graphene_type and not isinstance(graphene_type, str):
        qs = graphene_type._meta.model.objects
    elif model is not None:
        qs = model.objects

    is_object_type_with_double_id = str(graphene_type) in TYPES_WITH_DOUBLE_ID_AVAILABLE
    if is_object_type_with_double_id:
        nodes = _get_node_for_types_with_double_id(qs, pks, graphene_type)
    else:
        nodes = list(qs.filter(pk__in=pks))
        nodes.sort(key=lambda e: pks.index(str(e.pk)))  # preserve order in pks

    if not nodes:
        raise GraphQLError(ERROR_COULD_NO_RESOLVE_GLOBAL_ID % ids)

    nodes_pk_list = [str(node.pk) for node in nodes]
    if is_object_type_with_double_id:
        old_id_field = "number" if str(graphene_type) == "Order" else "old_id"
        nodes_pk_list.extend([str(getattr(node, old_id_field)) for node in nodes])
    for pk in pks:
        assert pk in nodes_pk_list, "There is no node of type {} with pk {}".format(
            graphene_type, pk
        )
    return nodes


def _get_node_for_types_with_double_id(qs, pks, graphene_type):
    uuid_pks = []
    old_pks = []
    is_order_type = str(graphene_type) == "Order"

    for pk in pks:
        try:
            uuid_pks.append(UUID(str(pk)))
        except ValueError:
            old_pks.append(pk)
    if is_order_type:
        lookup = Q(id__in=uuid_pks) | (Q(use_old_id=True) & Q(number__in=old_pks))
    else:
        lookup = Q(id__in=uuid_pks) | (Q(old_id__isnull=False) & Q(old_id__in=old_pks))
    nodes = list(qs.filter(lookup))
    old_id_field = "number" if is_order_type else "old_id"
    return sorted(
        nodes,
        key=lambda e: pks.index(
            str(e.pk) if e.pk in uuid_pks else str(getattr(e, old_id_field))
        ),
    )  # preserve order in pks


def format_permissions_for_display(permissions):
    """Transform permissions queryset into Permission list.

    Keyword Arguments:
        permissions - queryset with permissions

    """
    permissions_data = permissions.annotate(
        formated_codename=Concat("content_type__app_label", Value("."), "codename")
    ).values("name", "formated_codename")

    formatted_permissions = [
        Permission(
            code=PermissionEnum.get(data["formated_codename"]), name=data["name"]
        )
        for data in permissions_data
    ]
    return formatted_permissions


def get_user_or_app_from_context(context: "SaleorContext") -> Union[App, User, None]:
    # order is important
    # app can be None but user if None then is passed as anonymous
    return context.app or context.user


def requestor_is_superuser(requestor):
    """Return True if requestor is superuser."""
    return getattr(requestor, "is_superuser", False)


def query_identifier(document: GraphQLDocument) -> str:
    """Generate a fingerprint for a GraphQL query.

    For queries identifier is sorted set of all root objects separated by `,`.
    e.g
    query AnyQuery {
        product {
            id
        }
        order {
            id
        }
        Product2: product {
            id
        }
        Myself: me {
            email
        }
    }
    identifier: me, order, product

    For mutations identifier is mutation type name.
    e.g.
    mutation CreateToken{
        tokenCreate(...){
            token
        }
        deleteWarehouse(...){
            ...
        }
    }
    identifier: deleteWarehouse, tokenCreate
    """
    labels = []
    for definition in document.document_ast.definitions:
        if getattr(definition, "operation", None) in {
            "query",
            "mutation",
        }:
            selections = definition.selection_set.selections
            for selection in selections:
                labels.append(selection.name.value)
    if not labels:
        return "undefined"
    return ", ".join(sorted(set(labels)))


def query_fingerprint(document: GraphQLDocument) -> str:
    """Generate a fingerprint for a GraphQL query."""
    label = "unknown"
    for definition in document.document_ast.definitions:
        if getattr(definition, "operation", None) in {
            "query",
            "mutation",
            "subscription",
        }:
            if definition.name:
                label = f"{definition.operation}:{definition.name.value}"
            else:
                label = definition.operation
            break
    query_hash = hashlib.md5(document.document_string.encode("utf-8")).hexdigest()
    return f"{label}:{query_hash}"


def format_error(error, handled_exceptions):
    result: Dict[str, Any]
    if isinstance(error, GraphQLError):
        result = format_graphql_error(error)
    else:
        result = {"message": str(error)}

    if "extensions" not in result:
        result["extensions"] = {}

    exc = error
    while isinstance(exc, GraphQLError) and hasattr(exc, "original_error"):
        exc = exc.original_error
    if isinstance(exc, AssertionError):
        exc = GraphQLError(str(exc))
    if isinstance(exc, handled_exceptions):
        handled_errors_logger.info("A query had an error", exc_info=exc)
    else:
        unhandled_errors_logger.error("A query failed unexpectedly", exc_info=exc)

    result["extensions"]["exception"] = {"code": type(exc).__name__}
    if settings.DEBUG:
        lines = []

        if isinstance(exc, BaseException):
            for line in traceback.format_exception(type(exc), exc, exc.__traceback__):
                lines.extend(line.rstrip().splitlines())
        result["extensions"]["exception"]["stacktrace"] = lines
    return result

from collections import OrderedDict
from collections.abc import Iterable
from typing import Any, Dict, Optional

import graphene
from django.core.serializers.json import Serializer as JSONSerializer
from django.core.serializers.python import Serializer as PythonBaseSerializer
from django.utils.functional import SimpleLazyObject


class PythonSerializer(PythonBaseSerializer):
    def __init__(self, extra_model_fields=None):
        """Serialize a QuerySet to basic Python objects.

        Param extra_model_fields can be provided to add fields to serialization process
        which are normally ignored (fields that doesn't exist on model).
        extra_model_fields parameter example:
        {"ModelName": ["annotated_prop_1", "custom_property"]}
        """
        super().__init__()
        self.extra_model_fields = extra_model_fields

    def get_dump_object(self, obj):
        obj_id = graphene.Node.to_global_id(obj._meta.object_name, obj.id)
        data = OrderedDict([("type", str(obj._meta.object_name)), ("id", obj_id)])
        data.update(self._current)  # type: ignore[attr-defined] # internals of serializer # noqa: E501

        if obj._meta.object_name in self.extra_model_fields:
            fields_to_add = self.extra_model_fields[obj._meta.object_name]
            for field in fields_to_add:
                value = getattr(obj, field, None)
                if value is not None:
                    data.update({field: str(value)})

        return data


class PayloadSerializer(JSONSerializer):
    def __init__(self, extra_model_fields=None):
        super().__init__()
        self.extra_model_fields = extra_model_fields or {}
        self.additional_fields = {}
        self.extra_dict_data = {}
        self.obj_id_name = "id"
        self.pk_field_name = "id"
        self.dump_type_name = True

    def serialize(self, queryset, **options):
        self.additional_fields = options.pop("additional_fields", {})
        self.extra_dict_data = options.pop("extra_dict_data", {})
        self.obj_id_name = options.pop("obj_id_name", "id")
        self.pk_field_name = options.pop("pk_field_name", "id")
        self.dump_type_name = options.pop("dump_type_name", True)

        return super().serialize(
            queryset,
            stream=options.pop("stream", None),
            fields=options.pop("fields", None),
            use_natural_foreign_keys=options.pop("use_natural_foreign_keys", False),
            use_natural_primary_keys=options.pop("use_natural_primary_keys", False),
            progress_output=options.pop("progress_output", None),
            object_count=options.pop("object_count", 0),
            **options,
        )

    def get_dump_object(self, obj):
        obj_id = graphene.Node.to_global_id(
            obj._meta.object_name, getattr(obj, self.pk_field_name)
        )
        data: Dict[str, Optional[Any]] = {}
        if self.dump_type_name:
            data["type"] = str(obj._meta.object_name)
        data[self.obj_id_name] = obj_id

        # Evaluate and add the "additional fields"
        python_serializer = PythonSerializer(extra_model_fields=self.extra_model_fields)
        for field_name, (qs, fields) in self.additional_fields.items():
            data_to_serialize = qs(obj)
            if not data_to_serialize:
                data[field_name] = None
                continue
            # user can be attached to obj as a SimpleLazyObject. We need to unwrap it
            # before we will be able to serialize it.
            if isinstance(data_to_serialize, SimpleLazyObject):
                # FIXME: is this still required now that user is never empty?
                data_to_serialize = data_to_serialize._wrapped  # type: ignore[attr-defined] # noqa: E501

            if isinstance(data_to_serialize, Iterable):
                data[field_name] = python_serializer.serialize(
                    data_to_serialize, fields=fields
                )
            else:
                data[field_name] = python_serializer.serialize(
                    [data_to_serialize], fields=fields
                )[0]
        # Update the data with the  "extra dict data"
        called_data = {}
        for key, value in self.extra_dict_data.items():
            if callable(value):
                called_data[key] = value(obj)
        data.update(self.extra_dict_data)
        data.update(called_data)
        # Finally update the data with the super class' "self._current" content
        data.update(self._current)  # type: ignore[attr-defined] # internals of serializer # noqa: E501
        return data

